insert into public.levels (id, position, title, description) values
  ('00000000-0000-4000-8000-000000000101', 1, $$Làm quen$$, $$Câu đơn giản về bản thân, gia đình và đồ vật quanh em.$$),
  ('00000000-0000-4000-8000-000000000102', 2, $$Hằng ngày$$, $$Kể về thói quen, món ăn và ngôi nhà của bạn.$$),
  ('00000000-0000-4000-8000-000000000103', 3, $$Sở thích & con người$$, $$Mô tả sở thích, bạn bè và thời tiết.$$),
  ('00000000-0000-4000-8000-000000000104', 4, $$Kể chuyện$$, $$Kể lại chuyện đã qua bằng thì quá khứ đơn.$$),
  ('00000000-0000-4000-8000-000000000105', 5, $$Kế hoạch & ý kiến$$, $$Nói về tương lai, so sánh và nêu ý kiến của bạn.$$)
