  ('00000000-0000-4000-8000-000000000211', '00000000-0000-4000-8000-000000000101', 1, $$Giới thiệu bản thân$$, $$Tên, tuổi, nơi sống và công việc.$$, '🙋'),
  ('00000000-0000-4000-8000-000000000212', '00000000-0000-4000-8000-000000000101', 2, $$Gia đình$$, $$Các thành viên và nghề nghiệp của họ.$$, '👨‍👩‍👧'),
  ('00000000-0000-4000-8000-000000000213', '00000000-0000-4000-8000-000000000101', 3, $$Đồ vật quanh em$$, $$There is / there are, màu sắc, vị trí.$$, '🎒'),
  ('00000000-0000-4000-8000-000000000221', '00000000-0000-4000-8000-000000000102', 1, $$Thói quen hằng ngày$$, $$Giờ giấc và hoạt động mỗi ngày.$$, '⏰'),
  ('00000000-0000-4000-8000-000000000222', '00000000-0000-4000-8000-000000000102', 2, $$Đồ ăn$$, $$Món ăn yêu thích và thói quen ăn uống.$$, '🍜'),
  ('00000000-0000-4000-8000-000000000223', '00000000-0000-4000-8000-000000000102', 3, $$Nhà của em$$, $$Các phòng và đồ vật trong nhà.$$, '🏠'),
  ('00000000-0000-4000-8000-000000000231', '00000000-0000-4000-8000-000000000103', 1, $$Sở thích$$, $$Bạn làm gì khi rảnh và vì sao.$$, '🎨'),
  ('00000000-0000-4000-8000-000000000232', '00000000-0000-4000-8000-000000000103', 2, $$Bạn thân$$, $$Ngoại hình và tính cách của một người.$$, '🤝'),
  ('00000000-0000-4000-8000-000000000233', '00000000-0000-4000-8000-000000000103', 3, $$Thời tiết & mùa$$, $$Mùa trong năm và hoạt động theo mùa.$$, '🌦️'),
  ('00000000-0000-4000-8000-000000000241', '00000000-0000-4000-8000-000000000104', 1, $$Cuối tuần vừa rồi$$, $$Kể lại những việc đã làm.$$, '📅'),
  ('00000000-0000-4000-8000-000000000242', '00000000-0000-4000-8000-000000000104', 2, $$Một chuyến đi$$, $$Đi đâu, đi bằng gì, đã làm gì.$$, '✈️'),
  ('00000000-0000-4000-8000-000000000243', '00000000-0000-4000-8000-000000000104', 3, $$Một ngày đáng nhớ$$, $$Kể chuyện và cảm xúc.$$, '⭐'),
  ('00000000-0000-4000-8000-000000000251', '00000000-0000-4000-8000-000000000105', 1, $$Kế hoạch tương lai$$, $$Will và be going to.$$, '🚀'),
  ('00000000-0000-4000-8000-000000000252', '00000000-0000-4000-8000-000000000105', 2, $$So sánh$$, $$So sánh hơn: bigger, more expensive than…$$, '⚖️'),
  ('00000000-0000-4000-8000-000000000253', '00000000-0000-4000-8000-000000000105', 3, $$Nêu ý kiến đơn giản$$, $$I think…, because…, for example…$$, '💬')
