insert into public.exercises (id, topic_id, position, type, title, prompt, source_text, hints, min_words, max_words, reference_answer) values
-- Level 1 · Giới thiệu bản thân
('00000000-0000-4000-8000-000000003111', '00000000-0000-4000-8000-000000000211', 1, 'paragraph', $$Giới thiệu về bản thân$$,
 $$Hãy viết một đoạn văn ngắn giới thiệu bản thân: tên, tuổi, nơi bạn sống, bạn làm nghề gì hoặc học ở đâu, và một điều bạn thích. (Write about yourself: your name, age, where you live, your job or school, and one thing you like.)$$,
 null, $j${"vocabulary": ["name", "years old", "live in", "student", "work as", "like", "city", "favorite"], "starter": "Hello! My name is ..."}$j$, 25, 40, null),
('00000000-0000-4000-8000-000000003112', '00000000-0000-4000-8000-000000000211', 2, 'translate_vi_en', $$Dịch: Xin chào, tôi là Lan$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Xin chào, tên tôi là Lan. Tôi hai mươi tuổi. Tôi sống ở Hà Nội. Tôi là sinh viên.$$,
 $j${"vocabulary": ["my name is", "years old", "live in", "student"]}$j$, null, null,
 $$Hello, my name is Lan. I am twenty years old. I live in Hanoi. I am a student.$$),
('00000000-0000-4000-8000-000000003113', '00000000-0000-4000-8000-000000000211', 3, 'translate_en_vi', $$Dịch: Hi, I am Tom$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$Hi, I am Tom. I am from England. I am a teacher. I like music and coffee.$$,
 $j${"vocabulary": ["be from: đến từ", "teacher: giáo viên"]}$j$, null, null,
 $$Xin chào, tôi là Tom. Tôi đến từ nước Anh. Tôi là giáo viên. Tôi thích âm nhạc và cà phê.$$),
-- Level 1 · Gia đình
('00000000-0000-4000-8000-000000003121', '00000000-0000-4000-8000-000000000212', 1, 'paragraph', $$Gia đình của tôi$$,
 $$Viết về gia đình bạn: gia đình có mấy người, họ là ai và họ làm nghề gì. (Write about your family: how many people there are, who they are and what they do.)$$,
 null, $j${"vocabulary": ["family", "father", "mother", "brother", "sister", "people", "teacher", "doctor", "kind"], "starter": "There are ... people in my family."}$j$, 25, 40, null),
('00000000-0000-4000-8000-000000003122', '00000000-0000-4000-8000-000000000212', 2, 'translate_vi_en', $$Dịch: Gia đình tôi có bốn người$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Gia đình tôi có bốn người. Bố tôi là bác sĩ. Mẹ tôi là giáo viên. Tôi có một em gái.$$,
 $j${"vocabulary": ["there are", "doctor", "teacher", "younger sister"]}$j$, null, null,
 $$There are four people in my family. My father is a doctor. My mother is a teacher. I have a younger sister.$$),
('00000000-0000-4000-8000-000000003123', '00000000-0000-4000-8000-000000000212', 3, 'translate_en_vi', $$Dịch: My brother is ten$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$My brother is ten years old. He is tall and funny. He likes football. We play together every day.$$,
 $j${"vocabulary": ["funny: vui tính, hài hước", "together: cùng nhau"]}$j$, null, null,
 $$Em trai tôi mười tuổi. Em ấy cao và vui tính. Em ấy thích bóng đá. Chúng tôi chơi cùng nhau mỗi ngày.$$),
-- Level 1 · Đồ vật quanh em
('00000000-0000-4000-8000-000000003131', '00000000-0000-4000-8000-000000000213', 1, 'paragraph', $$Trong phòng của tôi$$,
 $$Mô tả những đồ vật trong phòng bạn: có những gì, màu gì và ở đâu. (Describe the things in your room: what they are, their colors and where they are.)$$,
 null, $j${"vocabulary": ["room", "bed", "desk", "chair", "lamp", "window", "there is", "there are", "next to", "on"], "starter": "This is my room."}$j$, 25, 40, null),
('00000000-0000-4000-8000-000000003132', '00000000-0000-4000-8000-000000000213', 2, 'translate_vi_en', $$Dịch: Trong phòng tôi$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Trong phòng tôi có một cái giường và một cái bàn. Cái bàn màu nâu. Có hai quyển sách trên bàn.$$,
 $j${"vocabulary": ["there is / there are", "bed", "desk", "brown", "on the desk"]}$j$, null, null,
 $$There is a bed and a desk in my room. The desk is brown. There are two books on the desk.$$),
('00000000-0000-4000-8000-000000003133', '00000000-0000-4000-8000-000000000213', 3, 'translate_en_vi', $$Dịch: My bag is blue$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$My bag is blue. There is a pen, a notebook and a phone in my bag. The phone is new.$$,
 $j${"vocabulary": ["bag: cặp, túi", "notebook: quyển vở"]}$j$, null, null,
 $$Cặp của tôi màu xanh dương. Trong cặp có một cây bút, một quyển vở và một chiếc điện thoại. Chiếc điện thoại còn mới.$$),
-- Level 2 · Thói quen hằng ngày
('00000000-0000-4000-8000-000000003211', '00000000-0000-4000-8000-000000000221', 1, 'paragraph', $$Một ngày của tôi$$,
 $$Kể về một ngày bình thường của bạn: mấy giờ bạn thức dậy, bạn làm gì vào buổi sáng, buổi chiều và buổi tối. (Describe your daily routine.)$$,
 null, $j${"vocabulary": ["get up", "have breakfast", "go to work", "go to school", "at ... o'clock", "usually", "always", "then", "go to bed"], "starter": "I usually get up at ..."}$j$, 35, 55, null),
('00000000-0000-4000-8000-000000003212', '00000000-0000-4000-8000-000000000221', 2, 'translate_vi_en', $$Dịch: Tôi thường thức dậy lúc sáu giờ$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Tôi thường thức dậy lúc sáu giờ. Tôi ăn sáng với gia đình. Sau đó tôi đi làm bằng xe máy. Buổi tối tôi xem tivi.$$,
 $j${"vocabulary": ["usually", "get up", "have breakfast", "by motorbike", "in the evening"]}$j$, null, null,
 $$I usually get up at six o'clock. I have breakfast with my family. Then I go to work by motorbike. In the evening, I watch TV.$$),
('00000000-0000-4000-8000-000000003213', '00000000-0000-4000-8000-000000000221', 3, 'translate_en_vi', $$Dịch: Mai gets up early$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$Mai gets up early every day. She drinks a glass of water and goes for a walk. She always reads a book before bed.$$,
 $j${"vocabulary": ["go for a walk: đi dạo", "before bed: trước khi đi ngủ"]}$j$, null, null,
 $$Mai dậy sớm mỗi ngày. Cô ấy uống một cốc nước và đi dạo. Cô ấy luôn đọc sách trước khi đi ngủ.$$),
-- Level 2 · Đồ ăn
('00000000-0000-4000-8000-000000003221', '00000000-0000-4000-8000-000000000222', 1, 'paragraph', $$Món ăn yêu thích$$,
 $$Viết về món ăn bạn thích nhất: tên món, trong món có gì, bạn thường ăn khi nào và ở đâu. (Write about your favorite food.)$$,
 null, $j${"vocabulary": ["favorite", "delicious", "rice", "noodles", "beef", "vegetables", "eat", "for breakfast", "sometimes", "restaurant"], "starter": "My favorite food is ..."}$j$, 35, 55, null),
('00000000-0000-4000-8000-000000003222', '00000000-0000-4000-8000-000000000222', 2, 'translate_vi_en', $$Dịch: Tôi rất thích phở bò$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Tôi rất thích phở bò. Phở có bánh phở, thịt bò và rau thơm. Tôi thường ăn phở vào buổi sáng.$$,
 $j${"vocabulary": ["really like", "rice noodles", "beef", "herbs", "in the morning"]}$j$, null, null,
 $$I really like beef pho. Pho has rice noodles, beef and herbs. I usually eat pho in the morning.$$),
('00000000-0000-4000-8000-000000003223', '00000000-0000-4000-8000-000000000222', 3, 'translate_en_vi', $$Dịch: I don't eat meat$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$I don't eat meat. I eat a lot of vegetables and fruit. My favorite fruit is mango because it is sweet.$$,
 $j${"vocabulary": ["meat: thịt", "mango: xoài", "sweet: ngọt"]}$j$, null, null,
 $$Tôi không ăn thịt. Tôi ăn nhiều rau và trái cây. Trái cây tôi thích nhất là xoài vì nó ngọt.$$),
-- Level 2 · Nhà của em
('00000000-0000-4000-8000-000000003231', '00000000-0000-4000-8000-000000000223', 1, 'paragraph', $$Ngôi nhà của tôi$$,
 $$Mô tả ngôi nhà hoặc căn hộ của bạn: ở đâu, có mấy phòng, bạn thích phòng nào nhất và vì sao. (Describe your home.)$$,
 null, $j${"vocabulary": ["house", "apartment", "floor", "living room", "kitchen", "bedroom", "bathroom", "small", "big", "garden"], "starter": "I live in a ..."}$j$, 35, 55, null),
('00000000-0000-4000-8000-000000003232', '00000000-0000-4000-8000-000000000223', 2, 'translate_vi_en', $$Dịch: Nhà tôi không lớn$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Nhà tôi không lớn nhưng rất ấm cúng. Nhà có ba phòng ngủ và một phòng bếp. Tôi thích phòng khách nhất.$$,
 $j${"vocabulary": ["cozy", "bedroom", "kitchen", "living room", "best"]}$j$, null, null,
 $$My house is not big, but it is very cozy. It has three bedrooms and a kitchen. I like the living room best.$$),
('00000000-0000-4000-8000-000000003233', '00000000-0000-4000-8000-000000000223', 3, 'translate_en_vi', $$Dịch: Our apartment$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$Our apartment is on the fifth floor. It has a small balcony with many flowers. My mother waters them every morning.$$,
 $j${"vocabulary": ["floor: tầng", "balcony: ban công", "water (v): tưới nước"]}$j$, null, null,
 $$Căn hộ của chúng tôi ở tầng năm. Căn hộ có một ban công nhỏ với nhiều hoa. Mẹ tôi tưới hoa mỗi sáng.$$),
-- Level 3 · Sở thích
('00000000-0000-4000-8000-000000003311', '00000000-0000-4000-8000-000000000231', 1, 'paragraph', $$Sở thích của tôi$$,
 $$Viết về một sở thích của bạn: đó là gì, bạn thường làm vào lúc nào, với ai, và vì sao bạn thích nó. (Write about your hobby: what it is, when and who you do it with, and why you like it.)$$,
 null, $j${"vocabulary": ["hobby", "enjoy", "in my free time", "because", "relax", "once a week", "with my friends", "interesting", "play the guitar", "take photos"], "starter": "In my free time, I like ..."}$j$, 45, 70, null),
('00000000-0000-4000-8000-000000003312', '00000000-0000-4000-8000-000000000231', 2, 'translate_vi_en', $$Dịch: Tôi thích chơi cầu lông$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Vào thời gian rảnh, tôi thích chơi cầu lông. Tôi chơi với bạn bè hai lần một tuần. Cầu lông giúp tôi khỏe mạnh và vui vẻ.$$,
 $j${"vocabulary": ["in my free time", "badminton", "twice a week", "help ... stay healthy"]}$j$, null, null,
 $$In my free time, I like playing badminton. I play with my friends twice a week. Badminton helps me stay healthy and happy.$$),
('00000000-0000-4000-8000-000000003313', '00000000-0000-4000-8000-000000000231', 3, 'translate_en_vi', $$Dịch: My sister loves drawing$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$My sister loves drawing. She draws animals and flowers. She wants to be an artist because drawing makes her happy.$$,
 $j${"vocabulary": ["draw: vẽ", "artist: họa sĩ", "make someone happy: làm ai đó vui"]}$j$, null, null,
 $$Chị gái tôi rất thích vẽ. Chị ấy vẽ động vật và hoa. Chị ấy muốn trở thành họa sĩ vì vẽ làm chị ấy vui.$$),
-- Level 3 · Bạn thân
('00000000-0000-4000-8000-000000003321', '00000000-0000-4000-8000-000000000232', 1, 'paragraph', $$Người bạn thân nhất$$,
 $$Mô tả người bạn thân nhất của bạn: ngoại hình, tính cách và những việc hai bạn thường làm cùng nhau. (Describe your best friend: appearance, personality and what you do together.)$$,
 null, $j${"vocabulary": ["best friend", "tall", "short hair", "kind", "friendly", "funny", "help", "together", "talk", "smile"], "starter": "My best friend is ..."}$j$, 45, 70, null),
('00000000-0000-4000-8000-000000003322', '00000000-0000-4000-8000-000000000232', 2, 'translate_vi_en', $$Dịch: Bạn thân nhất của tôi$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Bạn thân nhất của tôi tên là Minh. Cậu ấy cao, có mái tóc ngắn và luôn mỉm cười. Minh rất tốt bụng và hay giúp đỡ mọi người.$$,
 $j${"vocabulary": ["best friend", "short hair", "always smiles", "kind", "help other people"]}$j$, null, null,
 $$My best friend's name is Minh. He is tall, has short hair and always smiles. Minh is very kind and often helps other people.$$),
('00000000-0000-4000-8000-000000003323', '00000000-0000-4000-8000-000000000232', 3, 'translate_en_vi', $$Dịch: Anna is my best friend$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$Anna is my best friend. We met at school ten years ago. She is quiet but very funny. We often talk on the phone for hours.$$,
 $j${"vocabulary": ["met: đã gặp", "quiet: ít nói", "for hours: hàng giờ liền"]}$j$, null, null,
 $$Anna là bạn thân nhất của tôi. Chúng tôi gặp nhau ở trường mười năm trước. Cô ấy ít nói nhưng rất hài hước. Chúng tôi thường nói chuyện điện thoại hàng giờ liền.$$),
-- Level 3 · Thời tiết & mùa
('00000000-0000-4000-8000-000000003331', '00000000-0000-4000-8000-000000000233', 1, 'paragraph', $$Mùa tôi thích nhất$$,
 $$Viết về mùa bạn thích nhất trong năm: thời tiết thế nào, bạn thường làm gì vào mùa đó và vì sao bạn thích. (Write about your favorite season.)$$,
 null, $j${"vocabulary": ["season", "spring", "summer", "autumn", "winter", "weather", "hot", "cool", "rain", "sunny"], "starter": "My favorite season is ..."}$j$, 45, 70, null),
('00000000-0000-4000-8000-000000003332', '00000000-0000-4000-8000-000000000233', 2, 'translate_vi_en', $$Dịch: Mùa thu ở Hà Nội$$,
 $$Dịch đoạn sau sang tiếng Anh.$$,
 $$Ở Hà Nội, mùa thu rất đẹp. Thời tiết mát mẻ và trời thường có nắng. Tôi thích đi dạo quanh hồ vào mùa thu.$$,
 $j${"vocabulary": ["autumn", "cool", "sunny", "walk around the lake"]}$j$, null, null,
 $$In Hanoi, autumn is very beautiful. The weather is cool and it is often sunny. I like walking around the lake in autumn.$$),
('00000000-0000-4000-8000-000000003333', '00000000-0000-4000-8000-000000000233', 3, 'translate_en_vi', $$Dịch: It rains a lot$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$It rains a lot in the summer here. When it rains, I stay at home and drink hot tea. I like the sound of the rain.$$,
 $j${"vocabulary": ["stay at home: ở nhà", "sound: âm thanh, tiếng"]}$j$, null, null,
 $$Ở đây mùa hè mưa rất nhiều. Khi trời mưa, tôi ở nhà và uống trà nóng. Tôi thích tiếng mưa.$$),
-- Level 4 · Cuối tuần vừa rồi
('00000000-0000-4000-8000-000000003411', '00000000-0000-4000-8000-000000000241', 1, 'paragraph', $$Cuối tuần vừa rồi của tôi$$,
 $$Kể lại cuối tuần vừa rồi của bạn: bạn đã đi đâu, làm gì, với ai và cảm thấy thế nào. Hãy dùng thì quá khứ đơn. (Write about your last weekend using the past simple.)$$,
 null, $j${"vocabulary": ["last weekend", "on Saturday", "went", "visited", "watched", "ate", "met", "had a good time", "tired", "then"], "starter": "Last weekend, I ..."}$j$, 60, 90, null),
('00000000-0000-4000-8000-000000003412', '00000000-0000-4000-8000-000000000241', 2, 'translate_vi_en', $$Dịch: Thăm ông bà$$,
 $$Dịch đoạn sau sang tiếng Anh. Chú ý dùng thì quá khứ đơn.$$,
 $$Thứ Bảy tuần trước, tôi đến thăm ông bà. Chúng tôi nấu bữa trưa cùng nhau. Buổi chiều, tôi đi xem phim với một người bạn. Đó là một ngày rất vui.$$,
 $j${"vocabulary": ["last Saturday", "visited", "grandparents", "cooked", "went to the cinema"]}$j$, null, null,
 $$Last Saturday, I visited my grandparents. We cooked lunch together. In the afternoon, I went to the cinema with a friend. It was a very fun day.$$),
('00000000-0000-4000-8000-000000003413', '00000000-0000-4000-8000-000000000241', 3, 'translate_en_vi', $$Dịch: On Sunday morning$$,
 $$Dịch đoạn sau sang tiếng Việt.$$,
 $$On Sunday morning, I cleaned my room. After that, I went to the market and bought some fruit. In the evening, I called my parents.$$,
 $j${"vocabulary": ["cleaned: đã dọn dẹp", "bought: đã mua", "called: đã gọi điện"]}$j$, null, null,
